window.ROSCO_QUESTIONS={"1":{"green":[{"letter":"A","mode":"starts","clue":"Provincia andaluza donde se encuentra el desierto de Tabernas.","answer":"Almería","fact":"El desierto de Tabernas, en Almería, ha servido de escenario para numerosas películas.","aliases":[]},{"letter":"B","mode":"starts","clue":"¿Qué pensador andaluz es conocido como «Padre de la Patria Andaluza»? Escribe su nombre y apellido.","answer":"Blas Infante","fact":"Blas Infante impulsó los símbolos andaluces, como la bandera verdiblanca y la letra del himno.","aliases":[]},{"letter":"C","mode":"starts","clue":"Provincia andaluza en la que se encuentra Jerez de la Frontera.","answer":"Cádiz","fact":"Cádiz es una de las ocho provincias de Andalucía y tiene costas atlánticas.","aliases":[]},{"letter":"D","mode":"starts","clue":"Mes del año en el que se celebra el Día de la Bandera de Andalucía.","answer":"Diciembre","fact":"Se celebra el 4 de diciembre, en memoria de las manifestaciones por la autonomía de 1977.","aliases":[]},{"letter":"E","mode":"starts","clue":"Forma tradicional malagueña de preparar sardinas ensartadas en una caña y asadas a la brasa.","answer":"Espeto","fact":"Los espetos de sardinas son característicos del litoral de Málaga.","aliases":[]},{"letter":"F","mode":"starts","clue":"Arte andaluz que combina cante, baile y toque de guitarra.","answer":"Flamenco","fact":"El flamenco es Patrimonio Cultural Inmaterial de la Humanidad reconocido por la UNESCO.","aliases":[]},{"letter":"G","mode":"starts","clue":"Provincia andaluza en la que se encuentra la Alhambra.","answer":"Granada","fact":"La Alhambra es uno de los conjuntos monumentales más conocidos de Andalucía.","aliases":[]},{"letter":"H","mode":"starts","clue":"Provincia andaluza en la que se encuentra el Parque Nacional de Doñana, junto a Sevilla y Cádiz.","answer":"Huelva","fact":"Doñana se extiende por terrenos de Huelva, Sevilla y Cádiz.","aliases":[]},{"letter":"I","mode":"starts","clue":"Municipio costero de Huelva cuyo nombre lleva la palabra «Cristina».","answer":"Isla Cristina","fact":"Isla Cristina es conocida por su puerto y su tradición pesquera.","aliases":[]},{"letter":"J","mode":"starts","clue":"Provincia andaluza famosa por sus extensos olivares y su aceite de oliva.","answer":"Jaén","fact":"Jaén es una provincia estrechamente vinculada al cultivo del olivo.","aliases":[]},{"letter":"K","mode":"starts","clue":"Unidad de longitud equivalente a 1.000 metros, utilizada para medir rutas por Andalucía.","answer":"Kilómetro","fact":"Una ruta de 5 kilómetros equivale a 5.000 metros.","aliases":["Kilometro"]},{"letter":"L","mode":"starts","clue":"Felino protegido que habita en espacios naturales andaluces, como Doñana.","answer":"Lince ibérico","fact":"El lince ibérico es uno de los grandes símbolos de la conservación de la naturaleza en Andalucía.","aliases":[]},{"letter":"M","mode":"starts","clue":"Provincia de Andalucía famosa por la Costa del Sol y por el lugar de nacimiento de Picasso.","answer":"Málaga","fact":"Pablo Picasso nació en la ciudad de Málaga en 1881.","aliases":[]},{"letter":"N","mode":"starts","clue":"Localidad malagueña conocida por sus cuevas y el Balcón de Europa.","answer":"Nerja","fact":"La Cueva de Nerja es uno de los lugares patrimoniales más conocidos de Málaga.","aliases":[]},{"letter":"Ñ","mode":"contains","clue":"País en el que se encuentra la comunidad autónoma de Andalucía.","answer":"España","fact":"Andalucía es una de las comunidades autónomas de España.","aliases":[]},{"letter":"O","mode":"starts","clue":"Árbol del que se obtienen las aceitunas y el aceite de oliva.","answer":"Olivo","fact":"El olivo forma parte del paisaje agrícola de muchas zonas andaluzas.","aliases":[]},{"letter":"P","mode":"starts","clue":"Dulce tradicional que suele comerse en Navidad y por el que es conocida Estepa.","answer":"Polvorón","fact":"Estepa, en Sevilla, tiene una larga tradición en la elaboración de dulces navideños.","aliases":["Polvorones"]},{"letter":"Q","mode":"starts","clue":"Alimento elaborado a partir de leche, que puede ser de cabra de las sierras andaluzas.","answer":"Queso","fact":"En distintas comarcas andaluzas se elaboran quesos artesanos.","aliases":[]},{"letter":"R","mode":"starts","clue":"Nombre de la famosa romería que se celebra en una aldea de Almonte, en Huelva.","answer":"Rocío","fact":"La romería del Rocío es una de las celebraciones populares más conocidas de Andalucía.","aliases":[]},{"letter":"S","mode":"starts","clue":"Ciudad que es la capital de Andalucía.","answer":"Sevilla","fact":"Sevilla es la capital de la comunidad autónoma andaluza.","aliases":[]},{"letter":"T","mode":"starts","clue":"Localidad de Cádiz famosa por sus playas, el viento y su proximidad al estrecho de Gibraltar.","answer":"Tarifa","fact":"Tarifa es conocida internacionalmente por los deportes de viento.","aliases":[]},{"letter":"U","mode":"starts","clue":"Ciudad de Jaén que, junto a Baeza, es famosa por sus monumentos renacentistas.","answer":"Úbeda","fact":"Los conjuntos monumentales renacentistas de Úbeda y Baeza son Patrimonio Mundial.","aliases":[]},{"letter":"V","mode":"starts","clue":"Color que, junto al blanco, aparece en las tres franjas de la bandera andaluza.","answer":"Verde","fact":"La bandera de Andalucía tiene tres franjas horizontales: verde, blanca y verde.","aliases":[]},{"letter":"W","mode":"starts","clue":"Deporte que se practica sobre una tabla con vela y que es popular en Tarifa.","answer":"Windsurf","fact":"Las condiciones de viento del Estrecho favorecen deportes como el windsurf.","aliases":[]},{"letter":"X","mode":"contains","clue":"Nombre corto de la Exposición Universal celebrada en Sevilla en 1992.","answer":"Expo 92","fact":"La Exposición Universal de 1992 se celebró en Sevilla, en la isla de la Cartuja.","aliases":["Expo 1992"]},{"letter":"Y","mode":"starts","clue":"Hembra del caballo, animal de gran tradición ecuestre en Jerez de la Frontera.","answer":"Yegua","fact":"Jerez es conocida por sus tradiciones relacionadas con el caballo andaluz.","aliases":[]},{"letter":"Z","mode":"starts","clue":"Localidad de Cádiz cuyo nombre empieza por Z y es conocida por sus playas y el atún rojo.","answer":"Zahara de los Atunes","fact":"Zahara de los Atunes se encuentra en el litoral atlántico de Cádiz.","aliases":[]}],"white":[{"letter":"A","mode":"starts","answer":"Aceituna","clue":"Fruto del olivo del que se obtiene el famoso aceite de oliva de Andalucía.","fact":"Jaén es especialmente conocida por sus olivares, aunque hay producción en numerosas provincias.","aliases":[]},{"letter":"B","mode":"starts","answer":"Barbate","clue":"Pueblo costero gaditano conocido por su tradición pesquera y el atún de almadraba.","fact":"Barbate se encuentra en la comarca de La Janda, en la provincia de Cádiz.","aliases":[]},{"letter":"C","mode":"starts","answer":"Córdoba","clue":"Provincia andaluza famosa por su Mezquita-Catedral y sus patios floridos.","fact":"Los patios cordobeses son una de las grandes tradiciones de la ciudad.","aliases":[]},{"letter":"D","mode":"starts","answer":"Doñana","clue":"Espacio natural andaluz conocido por sus marismas, aves y linces ibéricos.","fact":"Doñana se extiende por áreas de Huelva, Sevilla y Cádiz.","aliases":[]},{"letter":"E","mode":"starts","answer":"Escudo","clue":"Símbolo andaluz en el que aparece Hércules entre dos columnas y con dos leones.","fact":"La bandera, el escudo y el himno son símbolos oficiales de Andalucía.","aliases":[]},{"letter":"F","mode":"starts","answer":"Feria","clue":"Fiesta popular andaluza con casetas, música y actividades festivas.","fact":"En Andalucía son conocidas ferias como la de Abril en Sevilla o la del Caballo en Jerez.","aliases":[]},{"letter":"G","mode":"starts","answer":"Gazpacho","clue":"Sopa fría andaluza elaborada normalmente con tomate, pimiento, pepino y aceite de oliva.","fact":"El gazpacho es uno de los platos más populares de la cocina andaluza.","aliases":[]},{"letter":"H","mode":"starts","answer":"Himno","clue":"Canción oficial de Andalucía que comienza con la expresión «La bandera blanca y verde».","fact":"La letra del himno fue escrita por Blas Infante.","aliases":[]},{"letter":"I","mode":"starts","answer":"Isla de la Cartuja","clue":"Zona de Sevilla donde se celebró la Exposición Universal de 1992.","fact":"La Expo 92 tuvo lugar en la isla de la Cartuja, junto al Guadalquivir.","aliases":[]},{"letter":"J","mode":"starts","answer":"Jerez de la Frontera","clue":"Ciudad gaditana conocida por sus vinos, sus caballos y su flamenco.","fact":"Jerez de la Frontera es una ciudad de la provincia de Cádiz.","aliases":[]},{"letter":"K","mode":"starts","answer":"Kitesurf","clue":"Deporte acuático con una tabla y una cometa que se practica en playas como las de Tarifa.","fact":"Los vientos de Tarifa favorecen deportes de vela y cometa.","aliases":[]},{"letter":"L","mode":"starts","answer":"Lunares","clue":"Dibujos redondos que aparecen habitualmente en muchos trajes de flamenca.","fact":"Los lunares son un motivo decorativo habitual en la indumentaria de feria.","aliases":[]},{"letter":"M","mode":"starts","answer":"Marismas","clue":"Terrenos bajos y húmedos muy importantes para las aves en Doñana.","fact":"Las marismas son ecosistemas destacados en el bajo Guadalquivir.","aliases":[]},{"letter":"N","mode":"starts","answer":"Nieve","clue":"Agua congelada que suele cubrir las zonas altas de Sierra Nevada en invierno.","fact":"Sierra Nevada es un macizo montañoso situado principalmente en Granada.","aliases":[]},{"letter":"Ñ","mode":"contains","answer":"Castañuelas","clue":"Instrumento de percusión que se toca con las manos en algunos bailes tradicionales.","fact":"Las castañuelas se utilizan en diversas danzas españolas, también en tradiciones andaluzas.","aliases":[]},{"letter":"O","mode":"starts","answer":"Ocho","clue":"Número de provincias que tiene Andalucía.","fact":"Las ocho provincias son Almería, Cádiz, Córdoba, Granada, Huelva, Jaén, Málaga y Sevilla.","aliases":[]},{"letter":"P","mode":"starts","answer":"Pescaíto frito","clue":"Plato de pescado rebozado y frito muy habitual en la costa andaluza.","fact":"Se sirve en muchas localidades de Cádiz, Málaga y otras zonas costeras.","aliases":["Pescaito frito","Pescado frito"]},{"letter":"Q","mode":"starts","answer":"Queso payoyo","clue":"Producto lácteo típico de la Sierra de Cádiz asociado a la cabra payoya.","fact":"La cabra payoya es una raza autóctona ligada a la Sierra de Cádiz.","aliases":[]},{"letter":"R","mode":"starts","answer":"Romería","clue":"Celebración en la que muchas personas se desplazan hasta una ermita o santuario.","fact":"La romería de El Rocío es una de las más conocidas de Andalucía.","aliases":[]},{"letter":"S","mode":"starts","answer":"Sierra Nevada","clue":"Cordillera andaluza donde se encuentra el Mulhacén.","fact":"El Mulhacén, en Sierra Nevada, es la cumbre más alta de la península ibérica.","aliases":[]},{"letter":"T","mode":"starts","answer":"Tortillitas de camarones","clue":"Especialidad gaditana elaborada con camarones y una masa fina que se fríe.","fact":"Son populares en la gastronomía de la bahía de Cádiz.","aliases":[]},{"letter":"U","mode":"starts","answer":"Utrera","clue":"Municipio sevillano con una importante tradición flamenca y de repostería.","fact":"Utrera, en Sevilla, es una de las localidades vinculadas a la historia del flamenco.","aliases":[]},{"letter":"V","mode":"starts","answer":"Villancico","clue":"Canción tradicional que suele cantarse en Navidad, también en zambombas jerezanas.","fact":"Las zambombas son una tradición navideña muy arraigada en Jerez de la Frontera.","aliases":[]},{"letter":"W","mode":"starts","answer":"Western","clue":"Género de películas de vaqueros que se ha rodado en el desierto de Tabernas.","fact":"Los paisajes de Tabernas, en Almería, han sido escenario de numerosos wésterns.","aliases":[]},{"letter":"X","mode":"contains","answer":"Axarquía","clue":"Comarca situada al este de la provincia de Málaga.","fact":"La Axarquía combina pueblos del interior, montañas y una costa mediterránea.","aliases":[]},{"letter":"Y","mode":"starts","answer":"Yemas de San Leandro","clue":"Dulce tradicional elaborado en un convento sevillano y famoso por su sabor a huevo.","fact":"Las yemas de San Leandro son un dulce conventual de Sevilla.","aliases":[]},{"letter":"Z","mode":"starts","answer":"Zahara de la Sierra","clue":"Pueblo blanco de Cádiz situado junto a un embalse y cerca de la sierra de Grazalema.","fact":"Zahara de la Sierra es una localidad de la Sierra de Cádiz, diferente de Zahara de los Atunes.","aliases":[]}]},"2":{"green":[{"letter":"A","mode":"starts","clue":"Conjunto monumental de Granada que fue residencia y fortaleza de gobernantes nazaríes.","answer":"Alhambra","fact":"La Alhambra reúne palacios, murallas, jardines e historia de la Granada andalusí.","aliases":[]},{"letter":"B","mode":"starts","clue":"Símbolo verde, blanco y verde al que se dedica oficialmente el 4 de diciembre en Andalucía.","answer":"Bandera","fact":"El 4D recuerda las movilizaciones por la autonomía andaluza de 1977.","aliases":["Bandera de Andalucía"]},{"letter":"C","mode":"starts","clue":"Ciudad andaluza en la que se encuentra la Mezquita-Catedral.","answer":"Córdoba","fact":"La Mezquita-Catedral es uno de los monumentos más conocidos de Córdoba.","aliases":[]},{"letter":"D","mode":"starts","clue":"Parque nacional famoso por sus marismas y sus aves migratorias, situado en el suroeste andaluz.","answer":"Doñana","fact":"Doñana es una zona de gran valor ecológico entre Huelva, Sevilla y Cádiz.","aliases":[]},{"letter":"E","mode":"starts","clue":"Norma fundamental que establece las instituciones y competencias de autogobierno de Andalucía.","answer":"Estatuto de Autonomía","fact":"El Estatuto de Autonomía para Andalucía es su norma institucional básica.","aliases":[]},{"letter":"F","mode":"starts","clue":"Manifestación cultural de cante, baile y toque que la UNESCO reconoció en 2010.","answer":"Flamenco","fact":"El flamenco fue inscrito en 2010 como Patrimonio Cultural Inmaterial de la Humanidad.","aliases":[]},{"letter":"G","mode":"starts","clue":"Río que pasa por Córdoba y Sevilla antes de desembocar en el océano Atlántico.","answer":"Guadalquivir","fact":"El Guadalquivir ha sido fundamental para la agricultura, el comercio y la historia andaluza.","aliases":[]},{"letter":"H","mode":"starts","clue":"Provincia donde está la aldea de El Rocío y parte de Doñana.","answer":"Huelva","fact":"El Rocío se encuentra en el municipio onubense de Almonte.","aliases":[]},{"letter":"I","mode":"starts","clue":"Población pesquera de Huelva situada en la costa occidental andaluza.","answer":"Isla Cristina","fact":"Isla Cristina destaca por su actividad pesquera y sus playas.","aliases":[]},{"letter":"J","mode":"starts","clue":"Provincia que acoge el Parque Natural de las Sierras de Cazorla, Segura y Las Villas.","answer":"Jaén","fact":"Este espacio natural protegido se encuentra en la provincia de Jaén.","aliases":[]},{"letter":"K","mode":"starts","clue":"Unidad de distancia utilizada para indicar la longitud de una ruta por Sierra Nevada.","answer":"Kilómetro","fact":"El kilómetro equivale a mil metros.","aliases":["Kilometro"]},{"letter":"L","mode":"starts","clue":"Ciudad de Jaén vinculada a la historia minera y a importantes torneos de ajedrez.","answer":"Linares","fact":"Linares fue un destacado centro de actividad minera e industrial.","aliases":[]},{"letter":"M","mode":"starts","clue":"Nombre del pico más alto de la península ibérica, situado en Sierra Nevada.","answer":"Mulhacén","fact":"El Mulhacén está en Granada y alcanza aproximadamente 3.479 metros.","aliases":[]},{"letter":"N","mode":"starts","clue":"Localidad malagueña famosa por su cueva prehistórica y el Balcón de Europa.","answer":"Nerja","fact":"En la Cueva de Nerja se conservan importantes restos y formaciones geológicas.","aliases":[]},{"letter":"Ñ","mode":"contains","clue":"País en cuya Constitución de 1978 se reconoce el derecho a la autonomía.","answer":"España","fact":"La Constitución española de 1978 abrió el marco del Estado de las Autonomías.","aliases":[]},{"letter":"O","mode":"starts","clue":"Extensión de terreno cubierta principalmente por olivos, muy característica de Jaén.","answer":"Olivar","fact":"Los olivares son una parte destacada de la economía y el paisaje andaluz.","aliases":[]},{"letter":"P","mode":"starts","clue":"Institución andaluza que aprueba leyes y cuya sede está en Sevilla.","answer":"Parlamento de Andalucía","fact":"El Parlamento ejerce la potestad legislativa de la comunidad autónoma.","aliases":[]},{"letter":"Q","mode":"starts","clue":"Producto tradicional elaborado con leche de cabra, presente en muchas comarcas serranas.","answer":"Queso de cabra","fact":"La ganadería caprina está presente en distintas zonas de Andalucía.","aliases":[]},{"letter":"R","mode":"starts","clue":"Ciudad malagueña famosa por su puente sobre el Tajo y por una asamblea andalucista de 1918.","answer":"Ronda","fact":"La Asamblea de Ronda de 1918 fue importante para los símbolos del andalucismo.","aliases":[]},{"letter":"S","mode":"starts","clue":"Capital andaluza cuyo casco histórico alberga la Giralda.","answer":"Sevilla","fact":"La Giralda es uno de los símbolos monumentales de Sevilla.","aliases":[]},{"letter":"T","mode":"starts","clue":"Civilización antigua que se desarrolló en el suroeste de la península ibérica.","answer":"Tartessos","fact":"Tartessos se relaciona con territorios del actual suroeste peninsular.","aliases":["Tarteso"]},{"letter":"U","mode":"starts","clue":"Ciudad jiennense cuyo patrimonio renacentista está reconocido junto con Baeza por la UNESCO.","answer":"Úbeda","fact":"Úbeda y Baeza fueron reconocidas como Patrimonio Mundial en 2003.","aliases":[]},{"letter":"V","mode":"starts","clue":"Palabra utilizada para describir a la bandera andaluza por la combinación de sus dos colores.","answer":"Verdiblanca","fact":"La bandera está compuesta por las franjas verde, blanca y verde.","aliases":[]},{"letter":"W","mode":"starts","clue":"Deporte de tabla y vela impulsado por el viento, muy practicado en Tarifa.","answer":"Windsurf","fact":"Tarifa es un lugar muy conocido para este deporte acuático.","aliases":[]},{"letter":"X","mode":"contains","clue":"Acontecimiento internacional celebrado en Sevilla en 1992, abreviado con una palabra que contiene X.","answer":"Expo 92","fact":"La Expo 92 se celebró en Sevilla y tuvo su recinto principal en la Cartuja.","aliases":["Expo 1992"]},{"letter":"Y","mode":"starts","clue":"Nombre de la hembra del caballo, vinculada a la tradición de la Real Escuela Andaluza del Arte Ecuestre.","answer":"Yegua","fact":"La Real Escuela Andaluza del Arte Ecuestre está situada en Jerez de la Frontera.","aliases":[]},{"letter":"Z","mode":"starts","clue":"Localidad gaditana famosa por sus almadrabas y por el atún rojo del Atlántico.","answer":"Zahara de los Atunes","fact":"Las almadrabas forman parte de la tradición pesquera de la costa gaditana.","aliases":[]}],"white":[{"letter":"A","mode":"starts","answer":"Alcázar","clue":"Palacio fortificado de origen medieval; el Real de Sevilla es uno de los más conocidos de Andalucía.","fact":"El Real Alcázar de Sevilla conserva arquitectura de distintas épocas.","aliases":[]},{"letter":"B","mode":"starts","answer":"Baelo Claudia","clue":"Ciudad romana cuyos restos se visitan junto a la playa de Bolonia, en Cádiz.","fact":"Baelo Claudia fue un núcleo romano relacionado con la pesca y la producción de salazones.","aliases":[]},{"letter":"C","mode":"starts","answer":"Cazorla","clue":"Localidad jiennense que da nombre a una famosa sierra y a un gran parque natural.","fact":"Cazorla está vinculada al Parque Natural de las Sierras de Cazorla, Segura y Las Villas.","aliases":[]},{"letter":"D","mode":"starts","answer":"Dolmen","clue":"Monumento prehistórico construido con grandes piedras; hay ejemplos célebres en Antequera.","fact":"Los dólmenes de Antequera forman parte del Patrimonio Mundial de la UNESCO.","aliases":[]},{"letter":"E","mode":"starts","answer":"Escudo","clue":"Emblema oficial de Andalucía en el que Hércules sujeta a dos leones.","fact":"El escudo andaluz incorpora dos columnas y la figura mitológica de Hércules.","aliases":[]},{"letter":"F","mode":"starts","answer":"Fandango","clue":"Palo o estilo musical y de baile tradicional con variedades en la provincia de Huelva.","fact":"En Huelva existe una arraigada tradición de fandangos.","aliases":[]},{"letter":"G","mode":"starts","answer":"Giralda","clue":"Torre emblemática de Sevilla que fue alminar y hoy es campanario de la catedral.","fact":"La Giralda conserva parte de la estructura del alminar almohade.","aliases":[]},{"letter":"H","mode":"starts","answer":"Hércules","clue":"Personaje mitológico que aparece entre dos columnas en el escudo andaluz.","fact":"En el escudo de Andalucía, Hércules representa la fuerza que domina los instintos.","aliases":[]},{"letter":"I","mode":"starts","answer":"Iznájar","clue":"Municipio del sur de Córdoba conocido por un gran embalse del río Genil.","fact":"Iznájar se encuentra en la comarca de la Subbética cordobesa.","aliases":[]},{"letter":"J","mode":"starts","answer":"Jerez de la Frontera","clue":"Ciudad gaditana donde se celebra la Feria del Caballo.","fact":"La Feria del Caballo de Jerez destaca por sus tradiciones ecuestres.","aliases":[]},{"letter":"K","mode":"starts","answer":"Kitesurf","clue":"Actividad acuática con tabla y cometa que aprovecha los fuertes vientos de Tarifa.","fact":"Tarifa es un destino muy conocido entre practicantes de kitesurf.","aliases":[]},{"letter":"L","mode":"starts","answer":"Lebrija","clue":"Localidad sevillana natal del cantaor flamenco Juan Peña «El Lebrijano».","fact":"Lebrija es un municipio de Sevilla muy vinculado a la cultura flamenca.","aliases":[]},{"letter":"M","mode":"starts","answer":"Mijas","clue":"Pueblo malagueño de casas blancas situado en las laderas de la sierra del mismo nombre.","fact":"Mijas es uno de los municipios conocidos de la Costa del Sol.","aliases":[]},{"letter":"N","mode":"starts","answer":"Niebla","clue":"Municipio onubense famoso por su recinto amurallado de origen medieval.","fact":"Niebla posee un importante patrimonio histórico, con murallas y puertas monumentales.","aliases":[]},{"letter":"Ñ","mode":"contains","answer":"Castañuelas","clue":"Instrumento que se hace sonar con los dedos y que acompaña algunos bailes.","fact":"Las castañuelas forman parte de diversas tradiciones musicales y coreográficas.","aliases":[]},{"letter":"O","mode":"starts","answer":"Ocho","clue":"Cantidad de provincias que integran la comunidad autónoma andaluza.","fact":"Andalucía está dividida administrativamente en ocho provincias.","aliases":[]},{"letter":"P","mode":"starts","answer":"Pueblos blancos","clue":"Conjunto de localidades de casas encaladas, especialmente famoso en las sierras de Cádiz y Málaga.","fact":"Los pueblos blancos son conocidos por sus fachadas blancas y su paisaje serrano.","aliases":[]},{"letter":"Q","mode":"starts","answer":"Queso payoyo","clue":"Queso tradicional de la Sierra de Cádiz relacionado con una raza local de cabras.","fact":"La leche de cabra payoya se emplea en quesos elaborados en la sierra gaditana.","aliases":[]},{"letter":"R","mode":"starts","answer":"Río Tinto","clue":"Curso de agua de Huelva conocido por sus características aguas rojizas.","fact":"El río Tinto y la cuenca minera onubense tienen gran interés geológico e histórico.","aliases":[]},{"letter":"S","mode":"starts","answer":"Salmorejo","clue":"Crema fría cordobesa hecha principalmente con tomate, pan, aceite de oliva y ajo.","fact":"El salmorejo cordobés se sirve a menudo con huevo y jamón.","aliases":[]},{"letter":"T","mode":"starts","answer":"Torre del Oro","clue":"Monumento de Sevilla situado a orillas del Guadalquivir que formó parte de las defensas de la ciudad.","fact":"La Torre del Oro es una torre histórica almohade de Sevilla.","aliases":[]},{"letter":"U","mode":"starts","answer":"Utrera","clue":"Ciudad sevillana conocida por su tradición flamenca y sus mostachones.","fact":"Los mostachones son un dulce típico de Utrera.","aliases":[]},{"letter":"V","mode":"starts","answer":"Veleta","clue":"Pico de Sierra Nevada situado cerca del Mulhacén, conocido por su altura y su perfil.","fact":"El Veleta es una de las montañas más conocidas de Sierra Nevada.","aliases":[]},{"letter":"W","mode":"starts","answer":"Western","clue":"Tipo de cine de vaqueros asociado a los antiguos decorados de películas de Tabernas.","fact":"La provincia de Almería ha acogido numerosos rodajes de wésterns.","aliases":[]},{"letter":"X","mode":"contains","answer":"Axarquía","clue":"Comarca malagueña situada entre las sierras y el Mediterráneo, al este de la capital.","fact":"La Axarquía es una comarca de Málaga con pueblos, montañas y costa.","aliases":[]},{"letter":"Y","mode":"starts","answer":"Yeguada","clue":"Conjunto de yeguas dedicadas a la cría de caballos; la tradición ecuestre es importante en Jerez.","fact":"La tradición ecuestre de la provincia de Cádiz está ligada a la cría y doma de caballos.","aliases":[]},{"letter":"Z","mode":"starts","answer":"Zalema","clue":"Variedad de uva blanca tradicionalmente cultivada en la provincia de Huelva.","fact":"La zalema es una uva característica de la zona vitivinícola del Condado de Huelva.","aliases":[]}]},"3":{"green":[{"letter":"A","mode":"starts","clue":"Capacidad de una comunidad de disponer de instituciones propias de gobierno, reivindicada en las manifestaciones del 4D de 1977.","answer":"Autonomía","fact":"El 4 de diciembre de 1977 se celebraron multitudinarias manifestaciones por la autonomía andaluza.","aliases":["Autogobierno"]},{"letter":"B","mode":"starts","clue":"Ciudad jiennense cuyo conjunto monumental renacentista es Patrimonio Mundial junto con Úbeda.","answer":"Baeza","fact":"Úbeda y Baeza destacan por su arquitectura renacentista.","aliases":[]},{"letter":"C","mode":"starts","clue":"Nombre que reciben las asambleas reunidas en Cádiz que aprobaron la Constitución española de 1812.","answer":"Cortes de Cádiz","fact":"La Constitución de 1812 fue aprobada por las Cortes reunidas en Cádiz.","aliases":[]},{"letter":"D","mode":"starts","clue":"Conmemoración oficial andaluza del 4 de diciembre, que recuerda las movilizaciones de 1977.","answer":"Día de la Bandera","fact":"El 4D fue declarado oficialmente Día de la Bandera de Andalucía mediante un decreto en 2022.","aliases":["Día de la Bandera de Andalucía"]},{"letter":"E","mode":"starts","clue":"Norma institucional básica que organiza el autogobierno de Andalucía.","answer":"Estatuto de Autonomía","fact":"La reforma vigente del Estatuto andaluz fue aprobada en 2007.","aliases":[]},{"letter":"F","mode":"starts","clue":"Fiesta sevillana de casetas, farolillos y trajes tradicionales que suele celebrarse en primavera.","answer":"Feria de Abril","fact":"La Feria de Abril es una de las grandes celebraciones de Sevilla.","aliases":[]},{"letter":"G","mode":"starts","clue":"Apellidos del joven malagueño fallecido durante la manifestación del 4 de diciembre de 1977.","answer":"García Caparrós","fact":"Manuel José García Caparrós murió en Málaga durante las movilizaciones por la autonomía.","aliases":["Garcia Caparros"]},{"letter":"H","mode":"starts","clue":"Personaje mitológico que aparece en el escudo andaluz entre dos columnas y junto a dos leones.","answer":"Hércules","fact":"El escudo oficial de Andalucía representa a Hércules sujetando dos leones.","aliases":[]},{"letter":"I","mode":"starts","clue":"Nombre de la antigua ciudad romana situada en el actual término de Santiponce, en Sevilla.","answer":"Itálica","fact":"En Itálica se conservan restos de la ciudad romana, entre ellos su anfiteatro.","aliases":["Italica"]},{"letter":"J","mode":"starts","clue":"Institución del gobierno autonómico andaluz integrada por Presidencia y Consejo de Gobierno, entre otros órganos.","answer":"Junta de Andalucía","fact":"La Junta de Andalucía es el conjunto de instituciones de autogobierno de la comunidad.","aliases":[]},{"letter":"K","mode":"starts","clue":"Unidad de potencia equivalente a mil vatios, habitual al hablar de instalaciones solares en Andalucía.","answer":"Kilovatio","fact":"El kilovatio (kW) mide potencia, mientras que el kilovatio-hora (kWh) mide energía.","aliases":["Kilowatt"]},{"letter":"L","mode":"starts","clue":"Franja de territorio en contacto con el mar y el océano; el andaluz incluye costas mediterráneas y atlánticas.","answer":"Litoral","fact":"Andalucía tiene costas en el mar Mediterráneo y el océano Atlántico.","aliases":[]},{"letter":"M","mode":"starts","clue":"Ciudad palatina califal cercana a Córdoba, reconocida como Patrimonio Mundial en 2018.","answer":"Medina Azahara","fact":"Medina Azahara se construyó en época del califato de Córdoba.","aliases":["Madinat al-Zahra","Madinat al Zahra"]},{"letter":"N","mode":"starts","clue":"Nombre de la dinastía que gobernó el último reino musulmán de Granada hasta 1492.","answer":"Nazarí","fact":"La dinastía nazarí gobernó el reino de Granada hasta su conquista en 1492.","aliases":["Nazaríes"]},{"letter":"Ñ","mode":"contains","clue":"Camino ganadero tradicional, de gran anchura, que forma parte de la red histórica de vías pecuarias.","answer":"Cañada real","fact":"Las cañadas reales conectaban lugares de pastoreo a través de grandes recorridos.","aliases":[]},{"letter":"O","mode":"starts","clue":"Río de la provincia de Huelva cuyas marismas constituyen un espacio natural protegido.","answer":"Odiel","fact":"Las Marismas del Odiel son una reserva de la biosfera y zona de gran importancia ecológica.","aliases":[]},{"letter":"P","mode":"starts","clue":"Órgano representativo de Andalucía que ejerce la función legislativa autonómica.","answer":"Parlamento de Andalucía","fact":"Los miembros del Parlamento andaluz son elegidos mediante sufragio.","aliases":[]},{"letter":"Q","mode":"starts","clue":"Municipio de Jaén vinculado al pintor Rafael Zabaleta y situado en el entorno de Cazorla.","answer":"Quesada","fact":"El Museo Rafael Zabaleta está en Quesada, Jaén.","aliases":[]},{"letter":"R","mode":"starts","clue":"Ciudad malagueña en la que se celebró una asamblea andalucista decisiva en 1918.","answer":"Ronda","fact":"La Asamblea de Ronda de 1918 acordó propuestas de símbolos andaluces.","aliases":[]},{"letter":"S","mode":"starts","clue":"Nombre del palacio sevillano que alberga la sede de la Presidencia de la Junta de Andalucía.","answer":"San Telmo","fact":"El Palacio de San Telmo se encuentra en Sevilla.","aliases":[]},{"letter":"T","mode":"starts","clue":"Nombre del proceso de cambio político español durante el que tuvieron lugar las movilizaciones andaluzas de 1977.","answer":"Transición","fact":"La Transición española coincidió con la reivindicación de la autonomía andaluza.","aliases":["Transición española"]},{"letter":"U","mode":"starts","clue":"Ciudad de Jaén declarada Patrimonio Mundial junto a Baeza por su arquitectura renacentista.","answer":"Úbeda","fact":"Úbeda conserva destacados palacios y edificios del Renacimiento.","aliases":[]},{"letter":"V","mode":"starts","clue":"Adjetivo que describe la bandera andaluza por su combinación de verde y blanco.","answer":"Verdiblanca","fact":"Es un nombre habitual de la bandera andaluza.","aliases":[]},{"letter":"W","mode":"starts","clue":"Deporte de navegación sobre una tabla con vela que aprovecha los vientos de Tarifa.","answer":"Windsurf","fact":"Los vientos de levante y poniente hacen de Tarifa un lugar destacado para este deporte.","aliases":[]},{"letter":"X","mode":"contains","clue":"Nombre abreviado de la Exposición Universal que se celebró en Sevilla en 1992.","answer":"Expo 92","fact":"La Expo 92 reunió pabellones de numerosos países.","aliases":["Expo 1992"]},{"letter":"Y","mode":"starts","clue":"Lugar donde se conservan o descubren restos de otras épocas, como ocurre en Baelo Claudia.","answer":"Yacimiento arqueológico","fact":"Baelo Claudia es una antigua ciudad romana conservada junto a la playa de Bolonia, en Cádiz.","aliases":[]},{"letter":"Z","mode":"starts","clue":"Fiesta o baile flamenco especialmente asociado al barrio del Sacromonte de Granada.","answer":"Zambra","fact":"La zambra está vinculada a la tradición flamenca granadina.","aliases":[]}],"white":[{"letter":"A","mode":"starts","answer":"Asamblea de Ronda","clue":"Reunión andalucista de 1918 en la que se impulsaron símbolos de Andalucía.","fact":"La Asamblea de Ronda de 1918 fue clave en la historia del andalucismo.","aliases":[]},{"letter":"B","mode":"starts","answer":"Bética","clue":"Nombre de la provincia romana que incluía gran parte de la actual Andalucía.","fact":"La Hispania Baetica tuvo como capital a Corduba, la actual Córdoba.","aliases":[]},{"letter":"C","mode":"starts","answer":"Carmona","clue":"Ciudad histórica de Sevilla conocida por sus puertas y su patrimonio romano y medieval.","fact":"Carmona conserva vestigios de diferentes etapas históricas.","aliases":[]},{"letter":"D","mode":"starts","answer":"Dólmenes de Antequera","clue":"Conjunto megalítico malagueño inscrito en la lista de Patrimonio Mundial de la UNESCO.","fact":"Los dólmenes de Antequera son monumentos funerarios construidos en la Prehistoria.","aliases":[]},{"letter":"E","mode":"starts","answer":"Emirato de Córdoba","clue":"Estado de al-Ándalus que se independizó políticamente de Bagdad en 756.","fact":"Abderramán I fundó el emirato independiente de Córdoba en el siglo VIII.","aliases":[]},{"letter":"F","mode":"starts","answer":"Fandango de Huelva","clue":"Cante flamenco tradicional característico de una provincia del occidente andaluz.","fact":"La provincia de Huelva cuenta con numerosos estilos locales de fandango.","aliases":[]},{"letter":"G","mode":"starts","answer":"Guadix","clue":"Localidad granadina conocida por un barrio de viviendas excavadas en cuevas.","fact":"Guadix es célebre por sus casas cueva y su patrimonio histórico.","aliases":[]},{"letter":"H","mode":"starts","answer":"Hispalis","clue":"Nombre latino de la ciudad que hoy conocemos como Sevilla.","fact":"Hispalis fue la denominación romana de Sevilla.","aliases":[]},{"letter":"I","mode":"starts","answer":"Ibn Rushd","clue":"Nombre árabe de Averroes, célebre filósofo nacido en Córdoba en el siglo XII.","fact":"Averroes, o Ibn Rushd, fue un filósofo andalusí vinculado a la Córdoba medieval.","aliases":[]},{"letter":"J","mode":"starts","answer":"Jerez de la Frontera","clue":"Ciudad de la provincia de Cádiz con una importante tradición vinícola y ecuestre.","fact":"Jerez es conocida por sus vinos de denominación de origen y por su cultura del caballo.","aliases":[]},{"letter":"K","mode":"starts","answer":"Karst","clue":"Tipo de relieve modelado por disolución de calizas, visible en enclaves como el Torcal.","fact":"El Torcal de Antequera es uno de los paisajes kársticos más conocidos de Andalucía.","aliases":[]},{"letter":"L","mode":"starts","answer":"Lorca","clue":"Apellido del poeta granadino Federico García, autor de «Romancero gitano».","fact":"Federico García Lorca es una figura fundamental de la literatura española del siglo XX.","aliases":[]},{"letter":"M","mode":"starts","answer":"Mezquita-Catedral","clue":"Monumento de Córdoba que conserva elementos del antiguo templo islámico y de la catedral cristiana.","fact":"La Mezquita-Catedral de Córdoba refleja distintas etapas de la historia de la ciudad.","aliases":[]},{"letter":"N","mode":"starts","answer":"Navas de Tolosa","clue":"Batalla de 1212 que tuvo lugar en el actual territorio de Jaén.","fact":"La batalla de las Navas de Tolosa tuvo gran importancia en la historia medieval peninsular.","aliases":[]},{"letter":"Ñ","mode":"contains","answer":"Peña flamenca","clue":"Asociación o local cultural donde se reúnen aficionados al cante y al baile.","fact":"Las peñas flamencas ayudan a difundir y conservar la tradición del flamenco.","aliases":[]},{"letter":"O","mode":"starts","answer":"Olavide","clue":"Apellido del ilustrado Pablo de ..., vinculado a las Nuevas Poblaciones de Sierra Morena.","fact":"Pablo de Olavide impulsó las Nuevas Poblaciones de Sierra Morena en el siglo XVIII.","aliases":[]},{"letter":"P","mode":"starts","answer":"Patios cordobeses","clue":"Espacios domésticos con flores y plantas que protagonizan una famosa fiesta de Córdoba.","fact":"La Fiesta de los Patios de Córdoba está incluida en el patrimonio cultural inmaterial de la UNESCO.","aliases":[]},{"letter":"Q","mode":"starts","answer":"Qurtuba","clue":"Nombre árabe usado para la ciudad de Córdoba durante al-Ándalus.","fact":"Qurtuba fue la denominación árabe medieval de Córdoba.","aliases":[]},{"letter":"R","mode":"starts","answer":"Renacimiento","clue":"Estilo artístico de los siglos XV y XVI muy visible en Úbeda y Baeza.","fact":"El patrimonio monumental de Úbeda y Baeza es representativo del Renacimiento español.","aliases":[]},{"letter":"S","mode":"starts","answer":"Sierra Morena","clue":"Cordillera que se extiende por el norte de Andalucía, separándola de la Meseta.","fact":"Sierra Morena forma parte del borde sur de la Meseta Central.","aliases":[]},{"letter":"T","mode":"starts","answer":"Torre del Oro","clue":"Torre defensiva de Sevilla a orillas del Guadalquivir de origen almohade.","fact":"La Torre del Oro forma parte del patrimonio histórico de Sevilla.","aliases":[]},{"letter":"U","mode":"starts","answer":"Universidad de Granada","clue":"Institución de educación superior fundada por Carlos I en 1531 en una ciudad andaluza.","fact":"La Universidad de Granada fue fundada en el siglo XVI.","aliases":[]},{"letter":"V","mode":"starts","answer":"Vega de Granada","clue":"Llanura fértil en torno a la ciudad de Granada, regada por ríos y acequias.","fact":"La Vega de Granada es una comarca agrícola con una larga historia de regadío.","aliases":[]},{"letter":"W","mode":"starts","answer":"Western","clue":"Género cinematográfico cuyos escenarios fueron recreados en Tabernas, Almería.","fact":"Los paisajes de Tabernas se usaron para rodar películas del oeste.","aliases":[]},{"letter":"X","mode":"contains","answer":"Axarquía","clue":"Comarca oriental malagueña con un paisaje de costa y montañas.","fact":"La Axarquía se sitúa al este de Málaga y cuenta con un destacado patrimonio rural.","aliases":[]},{"letter":"Y","mode":"starts","answer":"Yusuf I","clue":"Sultán nazarí del siglo XIV bajo cuyo mandato se construyó la Puerta de la Justicia de la Alhambra.","fact":"La Puerta de la Justicia de la Alhambra fue levantada en época de Yusuf I.","aliases":[]},{"letter":"Z","mode":"starts","answer":"Zirí","clue":"Nombre de la dinastía que gobernó la taifa de Granada durante parte del siglo XI.","fact":"Los ziríes desempeñaron un papel importante en la Granada medieval.","aliases":[]}]},"4":{"green":[{"letter":"A","mode":"starts","clue":"Precepto de la Constitución de 1978 que reguló la vía de acceso al autogobierno seguida por Andalucía en 1980.","answer":"Artículo 151","fact":"Andalucía impulsó el acceso a la autonomía por la vía contemplada en el artículo 151 de la Constitución.","aliases":["Artículo 151 de la Constitución"]},{"letter":"B","mode":"starts","clue":"Nombre y apellido del intelectual que impulsó la bandera, el escudo y la letra del himno andaluz.","answer":"Blas Infante","fact":"Blas Infante es reconocido como «Padre de la Patria Andaluza».","aliases":[]},{"letter":"C","mode":"starts","clue":"Norma fundamental española de 1978 que reconoce y garantiza el derecho a la autonomía de las nacionalidades y regiones.","answer":"Constitución","fact":"El artículo 2 de la Constitución española de 1978 reconoce el derecho a la autonomía.","aliases":["Constitución española","Constitución de 1978"]},{"letter":"D","mode":"starts","clue":"Norma aprobada en 2022 que declaró oficialmente el 4 de diciembre Día de la Bandera de Andalucía.","answer":"Decreto 541/2022","fact":"El Decreto 541/2022, de 8 de noviembre, reconoció oficialmente la efeméride del 4D.","aliases":["Decreto 541 de 2022"]},{"letter":"E","mode":"starts","clue":"Nombre de la norma institucional básica de Andalucía, reformada mediante Ley Orgánica 2/2007.","answer":"Estatuto de Autonomía","fact":"El Estatuto establece las instituciones, competencias y símbolos de Andalucía.","aliases":[]},{"letter":"F","mode":"starts","clue":"Poeta y dramaturgo granadino autor de «Bodas de sangre» y «La casa de Bernarda Alba».","answer":"Federico García Lorca","fact":"Federico García Lorca nació en Fuente Vaqueros (Granada) en 1898.","aliases":["Federico Garcia Lorca"]},{"letter":"G","mode":"starts","clue":"Apellidos de Manuel José, joven que falleció en Málaga durante las movilizaciones andaluzas del 4D de 1977.","answer":"García Caparrós","fact":"Manuel José García Caparrós murió en la manifestación por la autonomía de Málaga el 4 de diciembre de 1977.","aliases":["Garcia Caparros"]},{"letter":"H","mode":"starts","clue":"Héroe mitológico que, en el escudo de Andalucía, aparece entre columnas sujetando dos leones.","answer":"Hércules","fact":"El símbolo se inspira en la imagen clásica de Hércules y figura en el escudo oficial.","aliases":[]},{"letter":"I","mode":"starts","clue":"Ciudad hispanorromana de la Bética cuyos restos se encuentran en Santiponce, provincia de Sevilla.","answer":"Itálica","fact":"Itálica es un importante conjunto arqueológico romano junto a Sevilla.","aliases":["Italica"]},{"letter":"J","mode":"starts","clue":"Conjunto de instituciones de autogobierno de Andalucía, de acuerdo con su Estatuto.","answer":"Junta de Andalucía","fact":"Comprende el Parlamento, la Presidencia de la Junta y el Consejo de Gobierno.","aliases":[]},{"letter":"K","mode":"starts","clue":"Unidad del Sistema Internacional derivada del vatio, equivalente a 1.000 W, usada en proyectos solares andaluces.","answer":"Kilovatio","fact":"kW significa kilovatio y expresa potencia, no energía.","aliases":["Kilowatt"]},{"letter":"L","mode":"starts","clue":"Tipo de norma mediante la cual se aprobó la reforma del Estatuto de Andalucía en 2007; indica también su número y año.","answer":"Ley Orgánica 2/2007","fact":"La Ley Orgánica 2/2007, de 19 de marzo, reformó el Estatuto de Autonomía para Andalucía.","aliases":["Ley Orgánica 2 de 2007"]},{"letter":"M","mode":"starts","clue":"Documento político andalucista de 1919, llamado «... de Córdoba».","answer":"Manifiesto de Córdoba","fact":"El Manifiesto andalucista de Córdoba de 1919 fue un hito del andalucismo histórico.","aliases":["Manifiesto andalucista de Córdoba"]},{"letter":"N","mode":"starts","clue":"Dinastía musulmana que gobernó el reino de Granada entre los siglos XIII y XV.","answer":"Nazarí","fact":"Los nazaríes gobernaron el último reino musulmán de la península ibérica.","aliases":["Nazaríes"]},{"letter":"Ñ","mode":"contains","clue":"Vía pecuaria tradicional utilizada para el desplazamiento de ganado a larga distancia.","answer":"Cañada real","fact":"Las vías pecuarias forman parte del patrimonio histórico y territorial andaluz.","aliases":[]},{"letter":"O","mode":"starts","clue":"Río de Huelva que da nombre a unas marismas protegidas de gran valor para las aves migratorias.","answer":"Odiel","fact":"Las Marismas del Odiel forman parte de un estuario de gran importancia ecológica.","aliases":[]},{"letter":"P","mode":"starts","clue":"Institución autonómica elegida por la ciudadanía que ejerce la potestad legislativa en Andalucía.","answer":"Parlamento de Andalucía","fact":"El Parlamento andaluz tiene su sede en el antiguo Hospital de las Cinco Llagas de Sevilla.","aliases":[]},{"letter":"Q","mode":"starts","clue":"Expresión que nombra los 500 años transcurridos desde 1492 hasta 1992, año de la Expo de Sevilla.","answer":"Quinto centenario","fact":"La Exposición Universal de Sevilla de 1992 coincidió con la conmemoración de los 500 años de 1492.","aliases":["Quinto Centenario del Descubrimiento de América"]},{"letter":"R","mode":"starts","clue":"Consulta popular celebrada el 28 de febrero de 1980 sobre el proceso de autonomía andaluza.","answer":"Referéndum","fact":"El referéndum del 28F de 1980 fue un momento clave para el autogobierno andaluz.","aliases":["Referéndum de autonomía","Referéndum del 28F"]},{"letter":"S","mode":"starts","clue":"Palacio de Sevilla que es sede de la Presidencia de la Junta de Andalucía.","answer":"San Telmo","fact":"El Palacio de San Telmo es la sede de la Presidencia de la Junta.","aliases":[]},{"letter":"T","mode":"starts","clue":"Nombre convencional de la antigua civilización del suroeste peninsular relacionada con el valle del Guadalquivir.","answer":"Tartessos","fact":"Tartessos se estudia como una importante cultura de la Antigüedad del suroeste ibérico.","aliases":["Tarteso"]},{"letter":"U","mode":"starts","clue":"Adjetivo con el que se define a un parlamento compuesto por una sola cámara, como el andaluz.","answer":"Unicameral","fact":"El Parlamento de Andalucía es una asamblea legislativa de una sola cámara.","aliases":[]},{"letter":"V","mode":"starts","clue":"Expresión popular para la vía de acceso a la autonomía prevista en el artículo 151 de la Constitución.","answer":"Vía rápida","fact":"Andalucía accedió a la autonomía por el procedimiento del artículo 151.","aliases":["Vía rápida a la autonomía"]},{"letter":"W","mode":"starts","clue":"Modalidad deportiva de tabla y vela muy extendida en la zona de Tarifa, Cádiz.","answer":"Windsurf","fact":"Tarifa disfruta de vientos favorables para deportes de vela.","aliases":[]},{"letter":"X","mode":"contains","clue":"Evento internacional de 1992 que se celebró en la isla de la Cartuja, en Sevilla.","answer":"Expo 92","fact":"La Expo 92 fue la Exposición Universal celebrada en Sevilla.","aliases":["Expo 1992"]},{"letter":"Y","mode":"starts","clue":"Sultán nazarí que mandó construir en 1348 la Puerta de la Justicia de la Alhambra.","answer":"Yusuf I","fact":"El Patronato de la Alhambra atribuye la Puerta de la Justicia a Yusuf I en 1348.","aliases":["Yúsuf I","Yusuf primero"]},{"letter":"Z","mode":"starts","clue":"Expresión de baile y celebración flamenca muy vinculada al Sacromonte granadino.","answer":"Zambra","fact":"La zambra se asocia a la historia y cultura del Sacromonte de Granada.","aliases":[]}],"white":[{"letter":"A","mode":"starts","answer":"Asamblea de Ronda","clue":"Encuentro andalucista de 1918 en el que se adoptaron símbolos regionales.","fact":"La asamblea celebrada en Ronda en 1918 fue un hito del movimiento andalucista.","aliases":[]},{"letter":"B","mode":"starts","answer":"Bética","clue":"Provincia de Hispania durante el Imperio romano que tuvo su capital en Corduba.","fact":"La Bética fue una provincia romana que abarcó buena parte de la actual Andalucía.","aliases":[]},{"letter":"C","mode":"starts","answer":"Cortes de Cádiz","clue":"Asamblea que aprobó la Constitución española de 1812 en plena Guerra de la Independencia.","fact":"La Constitución de 1812 fue promulgada en Cádiz durante la Guerra de la Independencia.","aliases":[]},{"letter":"D","mode":"starts","answer":"Desamortización","clue":"Proceso histórico de venta de bienes de instituciones, especialmente eclesiásticas y municipales, en el siglo XIX.","fact":"Las desamortizaciones del siglo XIX transformaron la propiedad de la tierra en muchos lugares de Andalucía.","aliases":[]},{"letter":"E","mode":"starts","answer":"Emirato independiente de Córdoba","clue":"Estado andalusí fundado por Abderramán I en el año 756.","fact":"En 756 se fundó un emirato políticamente independiente del califato abasí, aunque no religioso.","aliases":[]},{"letter":"F","mode":"starts","answer":"Fernando III","clue":"Rey castellano que conquistó Sevilla en 1248.","fact":"Fernando III incorporó Sevilla a la Corona de Castilla en el siglo XIII.","aliases":["Fernando tercero","Fernando III de Castilla"]},{"letter":"G","mode":"starts","answer":"Giralda","clue":"Torre sevillana cuyo cuerpo inferior fue el alminar de una mezquita almohade.","fact":"La Giralda une arquitectura almohade y añadidos posteriores, como su campanario renacentista.","aliases":[]},{"letter":"H","mode":"starts","answer":"Hispalis","clue":"Nombre de Sevilla en la época romana.","fact":"Hispalis fue una ciudad destacada de la provincia romana de la Bética.","aliases":[]},{"letter":"I","mode":"starts","answer":"Ibn Rushd","clue":"Filósofo cordobés conocido en latín como Averroes que comentó la obra de Aristóteles.","fact":"Ibn Rushd, Averroes, destacó como filósofo, jurista y médico en al-Ándalus.","aliases":[]},{"letter":"J","mode":"starts","answer":"José del Castillo Díaz","clue":"Compositor de la música del himno de Andalucía, mientras que Blas Infante escribió la letra.","fact":"José del Castillo Díaz fue el autor de la música del himno andaluz.","aliases":[]},{"letter":"K","mode":"starts","answer":"Karst","clue":"Relieve producido por la disolución de rocas calizas, característico del Torcal de Antequera.","fact":"El Torcal de Antequera constituye un ejemplo de paisaje kárstico.","aliases":[]},{"letter":"L","mode":"starts","answer":"Liberalismo","clue":"Corriente política vinculada a la defensa de derechos y constituciones, presente en las Cortes de Cádiz de 1812.","fact":"La Constitución gaditana de 1812 fue un texto fundamental del liberalismo español.","aliases":[]},{"letter":"M","mode":"starts","answer":"Medina Azahara","clue":"Ciudad palatina califal situada cerca de Córdoba y fundada en el siglo X.","fact":"Medina Azahara, o Madinat al-Zahra, es Patrimonio Mundial de la UNESCO.","aliases":[]},{"letter":"N","mode":"starts","answer":"Navas de Tolosa","clue":"Nombre de una batalla librada en 1212 en territorio de la actual provincia de Jaén.","fact":"La batalla de las Navas de Tolosa fue un episodio destacado de la historia medieval.","aliases":[]},{"letter":"Ñ","mode":"contains","answer":"Peña flamenca","clue":"Entidad cultural de aficionados dedicada a promover y difundir el flamenco.","fact":"Las peñas flamencas mantienen espacios de encuentro y transmisión del flamenco.","aliases":[]},{"letter":"O","mode":"starts","answer":"Olavide","clue":"Apellido del político ilustrado que participó en la colonización de Sierra Morena en el siglo XVIII.","fact":"Pablo de Olavide estuvo relacionado con la creación de las Nuevas Poblaciones de Sierra Morena.","aliases":[]},{"letter":"P","mode":"starts","answer":"Pacto de Antequera","clue":"Acuerdo político de 1978 para impulsar la autonomía andaluza, suscrito por fuerzas políticas andaluzas.","fact":"El Pacto de Antequera de 1978 contribuyó a unir esfuerzos políticos en favor del autogobierno.","aliases":[]},{"letter":"Q","mode":"starts","answer":"Qurtuba","clue":"Topónimo árabe de Córdoba durante la etapa de al-Ándalus.","fact":"La Córdoba andalusí fue conocida en árabe como Qurtuba.","aliases":[]},{"letter":"R","mode":"starts","answer":"Ronda","clue":"Ciudad malagueña en la que se celebró una importante asamblea andalucista en 1918.","fact":"La Asamblea de Ronda de 1918 contribuyó a establecer símbolos del andalucismo.","aliases":[]},{"letter":"S","mode":"starts","answer":"Segunda República","clue":"Período político español iniciado en 1931 durante el que se plantearon propuestas autonómicas andaluzas.","fact":"Durante la Segunda República hubo intentos de elaborar un estatuto andaluz.","aliases":[]},{"letter":"T","mode":"starts","answer":"Transición","clue":"Etapa de cambio político a la democracia durante la que se celebraron las manifestaciones del 4D de 1977.","fact":"La Transición española incluyó la Constitución de 1978 y el proceso preautonómico andaluz.","aliases":[]},{"letter":"U","mode":"starts","answer":"Unión Europea","clue":"Organización supranacional a la que pertenece España desde 1986, entonces como Comunidad Económica Europea.","fact":"España se incorporó a las Comunidades Europeas en 1986.","aliases":[]},{"letter":"V","mode":"starts","answer":"Villa Alegría","clue":"Nombre de la casa de Blas Infante en Coria del Río que alberga memoria del andalucismo histórico.","fact":"La Casa de Blas Infante, conocida como Villa Alegría, se encuentra en Coria del Río.","aliases":[]},{"letter":"W","mode":"starts","answer":"Western","clue":"Género cinematográfico recreado en los decorados y paisajes del desierto de Tabernas.","fact":"Almería se convirtió en uno de los escenarios europeos más conocidos de rodajes del oeste.","aliases":[]},{"letter":"X","mode":"contains","answer":"Axarquía","clue":"Comarca de la provincia de Málaga situada al este de la capital y abierta al mar de Alborán.","fact":"La Axarquía es una comarca histórica y geográfica de Málaga.","aliases":[]},{"letter":"Y","mode":"starts","answer":"Yacimiento arqueológico","clue":"Lugar donde se estudian vestigios de épocas pasadas, como Baelo Claudia en la costa gaditana.","fact":"Baelo Claudia es un ejemplo de yacimiento romano visitable en Andalucía.","aliases":[]},{"letter":"Z","mode":"starts","answer":"Zirí","clue":"Dinastía que gobernó una taifa de Granada durante el siglo XI.","fact":"Los ziríes fueron protagonistas de la historia de la taifa granadina.","aliases":[]}]}};